export const MAP_BOUNDS = { lon0: 94.5, lon1: 141.5, lat0: 6.5, lat1: -11.5 } as const;
export const MAP_WIDTH = 1000;
export const MAP_HEIGHT = 383.0;

/** Koordinat (derajat) → titik di viewBox peta. */
export function projectToMap(lat: number, lon: number): { x: number; y: number } {
  const s = MAP_WIDTH / (MAP_BOUNDS.lon1 - MAP_BOUNDS.lon0);
  return { x: (lon - MAP_BOUNDS.lon0) * s, y: (MAP_BOUNDS.lat0 - lat) * s };
}

